import React, { useEffect, useState, useRef } from "react";
import { DataTable } from "primereact/datatable";
import { Column } from "primereact/column";
import { InputText } from "primereact/inputtext";
import { Messages } from "primereact/messages";
import GroepService from "../../../Services/GroepService";
import { Button } from "primereact/button";

export default function Groepen() {
  const [Groepen, SetGroepen] = useState(null);
  const msgs = useRef(null);

  const onRowEditComplete = (e) => {
    console.log(e);
    let _Groepen = [...Groepen];
    let { newData, index } = e;
    _Groepen[index] = newData;
    GroepService.Update(newData).then((result) => {
      console.log(result);
      try {
        if (result.data.type === "SUCCES") {
          SetGroepen(_Groepen);
          msgs.current.show({
            severity: "success",
            detail: " Update gelukt!",
            sticky: false,
          });
        } else {
          msgs.current.show({
            severity: "error",
            detail: result.data.payload.details,
            sticky: true,
          });
        }
      } catch {}
    });
  };

  const deleteColumn = () => {
    return (
      <Column
        key="delete"
        body={(rowData) => {
          return (
            <Button
              icon="pi pi-trash"
              className="p-button-rounded p-button-danger"
              onClick={() => deletegroep(rowData)}
            />
          );
        }}
      />
    );
  };

  const deletegroep = async (groep) => {
    if (window.confirm("Weet u zeker dat u deze groep wilt verwijderen?")) {
      msgs.current.show({
        severity: "info",
        detail: "Groep aan het verwijderen",
        sticky: false,
      });

      try {
        const response = await GroepService.Delete(groep.id);
        console.log(response.data);
        if (response.data.type === "SUCCES") {
          msgs.current.show({
            severity: "success",
            detail: "Groep verwijderd",
            sticky: false,
          });
          GroepService.GetAll().then((result) =>
            SetGroepen(result.data.payload),
          );
        } else {
          for (
            let index = 0;
            index < response.data.payload.details.length;
            ++index
          ) {
            msgs.current.show({
              severity: "error",
              detail: response.data.payload.details[index],
              sticky: true,
            });
          }
        }
      } catch {
        msgs.current.show({
          severity: "error",
          detail: "Groep verwijderen niet gelukt, probeer later opnieuw",
          sticky: true,
        });
      }
    }
  };

  const textEditor = (options) => {
    return (
      <InputText
        type="text"
        value={options.value}
        onChange={(e) => options.editorCallback(e.target.value)}
      />
    );
  };

  useEffect(() => {
    GroepService.GetAll().then((result) => SetGroepen(result.data.payload));
  }, []);

  return (
    <>
      <h1 style={{ marginLeft: "3vw" }}>Groepen</h1>
      <a href="/#/NieuweGroep" style={{ marginLeft: "4vw" }}>
        {" "}
        Nieuwe Groep
      </a>
      <Messages ref={msgs} />

      <div className="card">
        <DataTable
          onRowEditComplete={onRowEditComplete}
          editMode="row"
          dataKey="naam"
          value={Groepen}
          paginator
          rows={5}
          rowsPerPageOptions={[5, 10, 25, 50]}
          tableStyle={{ minWidth: "50rem" }}
        >
          {deleteColumn()}
          <Column
            rowEditor
            headerStyle={{ width: "10%", minWidth: "8rem" }}
            bodyStyle={{ textAlign: "left" }}
          ></Column>
          <Column
            field="naam"
            header="naam"
            sortable
            filter
            filterPlaceholder="Search"
            editor={(options) => textEditor(options)}
            style={{ width: "75%" }}
          ></Column>
        </DataTable>
      </div>
    </>
  );
}
