import * as XLSX from "xlsx";
import axios from "axios";
import SessionHandler from "../Sessionhandler/SessionHandler";

axios.defaults.headers.common.Authorization = "Bearer " + SessionHandler.getToken();
axios.defaults.headers.common["ClubID"] = SessionHandler.GetClub();

const LID_API_BASE_URL = process.env.REACT_APP_API_URL + "lid/bulk/nieuwlid";

class ExcelUploader {
  async parseFile(file) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();

      reader.onload = (event) => {
        try {
          const data = new Uint8Array(event.target.result);
          const workbook = XLSX.read(data, { type: "array" });

          // Assume first sheet
          const sheetName = workbook.SheetNames[0];
          const worksheet = workbook.Sheets[sheetName];
          const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

          // Skip header row, extract required columns
          const records = jsonData
            .slice(1)
            .map((row) => {
              const user = {
                voornaam: row[0],
                achternaam: row[1],
                email: row[2],
                groepstring: row[3],
              };

              // Remove empty fields
              Object.keys(user).forEach((key) => {
                if (!user[key] || String(user[key]).trim() === "") {
                  delete user[key];
                }
              });

              return user;
            })
            // Skip completely empty rows
            .filter((user) => Object.keys(user).length > 0);

          resolve(records);
        } catch (error) {
          reject(error);
        }
      };

      reader.onerror = reject;
      reader.readAsArrayBuffer(file);
    });
  }

  async sendToBackend(records) {
    return await axios({
      method: "post",
      url: LID_API_BASE_URL,
      headers: { "Content-Type": "application/json" },
      data: JSON.stringify({ leden: records }),
    }).catch(function (error) {
      if (error.response) {
        console.log(error.response.data);
        console.log(error.response.status);
        console.log(error.response.headers);
        return error.response;
      } else if (error.request) {
        console.log(error.request);
      } else {
        console.log("Error", error.message);
      }
      console.log(error.config);
    });
  }

  async handleFile(file) {
    try {
      const records = await this.parseFile(file);
      console.log("Parsed records:", records);

      const result = await this.sendToBackend(records);
      console.log("Backend response:", result);

      return result;
    } catch (error) {
      console.error("Error handling file:", error);
      throw error;
    }
  }
}

export default new ExcelUploader();
