const knownErrors = {
  TOS_REQUIRED: {
    match: function match(data, status) {
      return (
        (data && data.message === "TOS Required") ||
        (data && data.payload && data.payload.message === "TOS Required")
      );
    },
    handler: function handler() {
      console.warn("User must accept Terms of Service");
      // 🔽 Fire a global event that React can catch
      window.dispatchEvent(new CustomEvent("showTOS"));
    },
  },
  // other known errors...
};

export function handleAxiosError(error) {
  if (error.response) {
    const { status, data } = error.response;

    for (const key in knownErrors) {
      const { match, handler } = knownErrors[key];
      if (match(data, status)) {
        handler();
        return error.response;
      }
    }

    console.error("Unhandled error response:", { status, data });
    return error.response;
  } else if (error.request) {
    console.error("No response received:", error.request);
  } else {
    console.error("Axios request setup error:", error.message);
  }

  console.error("Axios config:", error.config);
  return null;
}
