import React, { useEffect, useState, useRef } from "react";
import LidService from "../../../Services/LidService";
import GroepService from "../../../Services/GroepService";
import { DataTable } from "primereact/datatable";
import { Column } from "primereact/column";
import { Messages } from "primereact/messages";
import { Dropdown } from "primereact/dropdown";
import RolService from "../../../Services/RolService";
import { Button } from "primereact/button";

export default function LedenLijst() {
  const [leden, setLeden] = useState([]);
  const [groepen, setGroepen] = useState([]);
  const [rollen, setRollen] = useState([]);
  const msgs = useRef(null);

  const find = () => {
    setLeden(null);
    setGroepen(null);
    setRollen(null);
    LidService.GetAll().then((result) => setLeden(result.data.payload));
    GroepService.GetAll().then((result) => setGroepen(result.data.payload));
    RolService.GetAll().then((result) => setRollen(result.data.payload));
  };

  useEffect(() => {
    find();
  }, []);

  const deleteColumn = () => {
    return (
      <Column
        key="delete"
        body={(rowData) => {
          return (
            <Button
              icon="pi pi-trash"
              className="p-button-rounded p-button-danger"
              onClick={() => deleteLidVanClub(rowData)}
            />
          );
        }}
        style={{ width: "6rem", textAlign: "center" }}
      />
    );
  };

  const deleteLidVanClub = async (lid) => {
    if (window.confirm("Weet u zeker dat u dit lid wilt verwijderen?")) {
      msgs.current.show({
        severity: "info",
        detail: "Lid aan het verwijderen",
        sticky: false,
      });

      try {
        const response = await LidService.DeleteFromClub(lid.id);
        console.log(response.data);
        if (response.data.type === "SUCCES") {
          msgs.current.show({
            severity: "success",
            detail: "Lid verwijderd",
            sticky: false,
          });
          find();
        } else {
          for (
            let index = 0;
            index < response.data.payload.details.length;
            ++index
          ) {
            msgs.current.show({
              severity: "error",
              detail: response.data.payload.details[index],
              sticky: true,
            });
          }
        }
      } catch {
        msgs.current.show({
          severity: "error",
          detail: "Lid verwijderen niet gelukt, probeer later opnieuw",
          sticky: true,
        });
      }
    }
  };

  const onRowEditComplete = (e) => {
    const updatedLeden = [...leden];
    const { newData, index } = e;
    console.log("Rol is");
    console.log(newData.groep);

    if (newData.groep.naam != null) {
      newData.groep = newData.groep.id;
    }

    updatedLeden[index] = newData;

    LidService.UpdateClubConnectie(newData).then((result) => {
      if (result.data.type === "SUCCES") {
        setLeden(updatedLeden);
        msgs.current.show({ severity: "success", detail: "Update gelukt!" });
        find();
      } else {
        msgs.current.show({
          severity: "error",
          detail: result.data.payload.details,
          sticky: true,
        });
      }
    });
  };

  const dropdownEditor = (options, items) => {
    const value = options.value ? options.value.id || options.value : null;
    return (
      <Dropdown
        value={value}
        options={[
          { label: "Geen groep", value: null }, // Option for "no group"
          ...items.map((item) => ({ label: item.naam, value: item.id })),
        ]}
        onChange={(e) => options.editorCallback(e.value)}
        placeholder="Selecteer"
      />
    );
  };

  const dropdownEditor2 = (options, items) => {
    const value = options.value ? options.value.naam || options.value : null;
    return (
      <Dropdown
        value={value}
        options={items.map((item) => ({ label: item.naam, value: item.naam }))}
        onChange={(e) => options.editorCallback(e.value)}
        placeholder="Selecteer"
      />
    );
  };

  const groepBodyTemplate = (rowData) => {
    return rowData.groep ? rowData.groep.naam : ""; // Show empty string when no group is assigned
  };

  const rolBodyTemplate = (rowData) => {
    return rowData.rol ? rowData.rol.naam : "";
  };

  return (
    <>
      <h1 style={{ marginLeft: "3vw" }}>Leden</h1>
      <a style={{ marginLeft: "4vw" }} href="/#/NieuwLid">
        Nieuw lid
      </a>
      <Messages ref={msgs} />
      <div className="card">
        <DataTable
          value={leden}
          editMode="row"
          dataKey="id"
          paginator
          rows={25}
          rowsPerPageOptions={[5, 10, 25, 50, 100]}
          onRowEditComplete={onRowEditComplete}
          tableStyle={{ minWidth: "50rem" }}
        >
          {deleteColumn()}
          <Column
            rowEditor
            headerStyle={{ width: "10%", minWidth: "8rem" }}
            bodyStyle={{ textAlign: "center" }}
          />
          <Column
            field="voornaam"
            header="Voornaam"
            sortable
            filter
            filterPlaceholder="Search"
            style={{ width: "25%" }}
          />
          <Column
            field="achternaam"
            header="Achternaam"
            sortable
            filter
            filterPlaceholder="Search"
            style={{ width: "25%" }}
          />
          <Column
            sortField="groep.naam"
            field="groep"
            header="Groep"
            sortable
            filter
            filterField="groep.naam"
            filterPlaceholder="Search"
            editor={(options) => dropdownEditor(options, groepen)}
            body={groepBodyTemplate}
            style={{ width: "25%" }}
          />
          <Column
            field="email"
            header="Email"
            sortable
            filter
            filterPlaceholder="Search"
            style={{ width: "25%" }}
          />
          <Column
            field="telnummer"
            header="Telefoon nummer"
            sortable
            filter
            filterPlaceholder="Search"
            style={{ width: "25%" }}
          />
          <Column
            field="geboortedatum"
            header="Geboortedatum"
            sortable
            filter
            filterPlaceholder="Search"
            style={{ width: "25%" }}
          />
          <Column
            field="rol"
            header="Rol"
            sortable
            sortField="rol.naam"
            filter
            filterField="rol.naam"
            filterPlaceholder="Search"
            editor={(options) => dropdownEditor2(options, rollen)}
            body={rolBodyTemplate}
            style={{ width: "25%" }}
          />
        </DataTable>
      </div>
    </>
  );
}
