import axios from "axios";
import SessionHandler from "../Sessionhandler/SessionHandler";
import { handleAxiosError } from "./RequestErrorHandeling";

// Set global headers (same as before)
axios.defaults.headers.common.Authorization = "Bearer " + SessionHandler.getToken();
axios.defaults.headers.common["ClubID"] = SessionHandler.GetClub();

// Automatically run your handleAxiosError() for all failed requests
axios.interceptors.response.use(
  (response) => response, // normal responses just pass through
  (error) => {
    handleAxiosError(error);
    // Important: return a rejected promise so code using .then()/.catch() still works
    return Promise.reject(error);
  }
);

// Export so all services import this once
export default axios;